// Run from any directory; generated catalog contains token names, never hex values.
const { readFileSync, writeFileSync } = require('node:fs');
const { resolve } = require('node:path');
const tokens = JSON.parse(readFileSync(resolve(__dirname, '../../../packages/design-tokens/tokens.json'), 'utf8'));
function leaves(node, prefix = '') {
  return Object.entries(node).flatMap(([key, value]) => typeof value === 'string' ? [`${prefix}${key}`] : leaves(value, `${prefix}${key}.`));
}
writeFileSync(resolve(__dirname, '../src/modules/categories/category-tokens.generated.ts'),
  '// Generated by scripts/generate-category-tokens.cjs from packages/design-tokens/tokens.json.\n' +
  `export const CATEGORY_COLORS = ${JSON.stringify(leaves({ color: tokens.color }), null, 2)} as const;\n`);
